"use strict";
// Recognized voicemail/call-screening prompts only; a person discussing them is not a machine.
const normalize = (value) =>
  String(value || "")
    .normalize("NFKC")
    .replace(/’/g, "'")
    .trim();
const discussingGreeting =
  /^(?:my|our) (?:voice[ -]?mail|mailbox) (?:is|was|has)\b|^(?:what|how|why|can (?:I|you)|could (?:I|you)|do you|is this|are you)\b|\b(?:I (?:said|heard|got|received|left)|you (?:said|mentioned)|(?:it|he|she|they) (?:said|says)|(?:my|your|the) (?:voice[ -]?mail|mailbox) (?:said|says)|why (?:did|was|is)|can you|could you)\b|\bI (?:want|need|would like|plan|tried|try|will) (?:to )?(?:leave|record|send)\b|\bI(?:'d| would) like to (?:leave|record|send)\b/i;

function answeringPrompt(text) {
  return (
    /\bif you know (?:your party'?s|the|their) extension\b.{0,90}\b(?:dial|enter|key in) (?:it|the extension)\b/i.test(
      text,
    ) ||
    /\b(?:choose|select) (?:from )?(?:one of )?(?:the following |these )?options\b.{0,120}\b(?:press|dial|enter) (?:\d|zero|one|two|three|four|five|six|seven|eight|nine)\b/i.test(
      text,
    ) ||
    /\bfor [\w' -]{2,45} (?:press|dial) (?:\d|zero|one|two|three|four|five|six|seven|eight|nine)\b.{0,60}\bfor [\w' -]{2,45} (?:press|dial) (?:\d|zero|one|two|three|four|five|six|seven|eight|nine)\b/i.test(
      text,
    ) ||
    /^(?:(?:hi|hello|hey) )?(?:please )?(?:leave|record) (?:me |us )?(?:a |your )?(?:voice[ -]?)?message (?:(?:or|alternatively|oh|uh) )?(?:please )?(?:(?:send|drop) (?:me |us )?(?:a |your )?(?:text(?: message)?|sms)|text (?:me|us))\b/i.test(
      text,
    ) ||
    /\b(?:sorry (?:I|we) missed (?:your|the) call|(?:I|we)(?:'m|'re| am| are) (?:away from (?:my|our|the) (?:desk|phone)|(?:currently )?unavailable|on (?:another|the) (?:line|call)))\b.{0,100}\b(?:leave|record) (?:me |us )?(?:a |your )?message\b/i.test(
      text,
    ) ||
    /\b(?:leave|record) (?:me |us )?(?:a |your )?(?:voice[ -]?)?message\b.{0,100}\b(?:once|when|following) (?:you hear )?(?:the|a) (?:beep|tone)\b/i.test(
      text,
    )
  );
}

function isVoicemailGreeting(value, recent = []) {
  const text = normalize(value);
  if (!text || discussingGreeting.test(text)) return false;
  // Carrier announcements and connection challenges are machines too. Never
  // infer this from "thank you for calling", a number or unavailability alone.
  if (
    /(?:\b(?:your|this) call |^)(?:has been|is being|was) forwarded (?:to )?(?:a |the )?voice[ -]?mail\b/i.test(
      text,
    ) ||
    /\b(?:your|this) call\b[\s\S]{0,160}\b(?:has been|is|was) blocked\b[\s\S]{0,100}\b(?:protect|security|spam|scam|robocall)\b/i.test(
      text,
    ) ||
    /\b(?:network security provider|automated call protection)\b[\s\S]{0,180}\b(?:robocall|spam|scam|blocked)\b/i.test(
      text,
    ) ||
    /\b(?:please )?press (?:one|1|two|2|a key|any key)\b[\s\S]{0,80}\b(?:connect|complete|accept) (?:your |the |this )?call\b/i.test(
      text,
    ) ||
    /\b(?:to )?(?:connect|complete) (?:your |the |this )?call[, ]+(?:please )?press (?:one|1|two|2|a key|any key)\b/i.test(
      text,
    )
  )
    return true;
  // STT may split the connection challenge into "One" / "To connect your
  // call". Require the greeting, digit and connection clause in nearby turns.
  const fragments = [...recent.slice(-3).map(normalize), text];
  const context = fragments
    .slice(
      fragments.findLastIndex((fragment) => discussingGreeting.test(fragment)) +
        1,
    )
    .join(" ");
  // Carrier and mailbox recordings observed in live calls often arrive in
  // separate recognition fragments. Require distinctive recorded prompts.
  if (
    /^welcome to verizon wireless\b/i.test(text) ||
    /\b(?:voicemail|voice mail) box\b[\s\S]{0,80}\b(?:not been set up|not set up|hasn't been set up)\b/i.test(
      context,
    ) ||
    /\b(?:to )?(?:review|re-record|rerecord|add to|send|mark) (?:your |the )?message\b[\s\S]{0,100}\bpress\s+(?:\w+|\d+)\b/i.test(
      context,
    ) ||
    /\b(?:please )?hang up and (?:try|dial)\b/i.test(text) ||
    /\b(?:unable to authenticate your phone|announcement \w+ switch|your message has been sent)\b/i.test(
      text,
    ) ||
    /\b(?:thanks|thank you) for calling\b[\s\S]{0,100}\bpress (?:one|1|two|2|a key|any key)\b[\s\S]{0,100}\b(?:connect|agent)\b/i.test(
      context,
    ) ||
    /\bnetwork security provider\b[\s\S]{0,180}\b(?:blocked|protect|automated)\b/i.test(
      context,
    ) ||
    /\b(?:forwarded to an? automatic voice|mailbox belonging to)\b[\s\S]{0,150}\b(?:full|not receive|unavailable)\b/i.test(
      context,
    )
  )
    return true;
  if (
    /^to connect your call[.! ]*$/i.test(text) &&
    /\bthank you for calling\b[\s\S]{0,100}\b(?:one|1|two|2)\b/i.test(context)
  )
    return true;
  // A call-screening recorder is also a machine, not a customer answering a question.
  const screening =
    /\brecord (?:your |a )?name(?:[\s,]+and)? (?:the |your )?reason for (?:(?:the|your) )?call(?:ing)?\b/i.test(
      context,
    ) ||
    /\b(?:record|say) (?:your )?name\b[\s\S]{0,100}\b(?:I(?:'ll| will)|we(?:'ll| will)) (?:see|check) if (?:this|the) person is available\b/i.test(
      context,
    ) ||
    /\brecord (?:your )?name\b[\s\S]{0,100}\b(?:after|at) (?:the )?(?:tone|beep)\b/i.test(
      context,
    ) ||
    /\b(?:this call|your call) (?:is being|has been) screened\b[\s\S]{0,100}\b(?:name|reason|record)\b/i.test(
      context,
    );
  if (screening) return true;
  const clean = (value) =>
    value
      .replace(/[.!?,:;]+/g, " ")
      .replace(/\s+/g, " ")
      .trim();
  const prompt = clean(context);
  return (
    answeringPrompt(clean(text)) ||
    answeringPrompt(prompt) ||
    /\b(?:at|after) (?:the|a) (?:tone|beep)\b.{0,120}\b(?:record|leave) (?:me |us )?(?:a |your )?(?:voice[ -]?)?message\b/i.test(prompt) ||
    /\bthe (?:person|subscriber) you(?:'re| are) (?:trying to reach|calling) (?:is not|isn't) available\b.{0,100}\b(?:at|after) the (?:tone|beep)\b/i.test(prompt) ||
    /\b(?:at the sound of|when you hear) (?:the |a )?(?:beep|tone|signal)\b.{0,100}\b(?:leave|record|say) (?:me |us )?(?:a |your )?(?:voice[ -]?)?message\b/i.test(
      prompt,
    ) ||
    /\b(?:you may|please) (?:begin|start) (?:speaking|recording)\b.{0,75}\b(?:after|at) (?:you hear )?(?:the |a )?(?:tone|beep|beat|beap|signal)\b/i.test(
      prompt,
    ) ||
    /\b(?:when|once) (?:you (?:have )?finished|you're done)\b.{0,100}\b(?:hang up or press|press (?:pound|the pound key|hash) to (?:send|save))\b/i.test(
      prompt,
    ) ||
    /\b(?:voice[ -]?mail|message|mailbox) (?:is )?(?:full|not (?:yet )?set up|has not been set up|cannot accept messages)\b/i.test(
      text,
    ) ||
    /\b(?:please )?record (?:a |your )?message\b[\s\S]{0,100}\b(?:after|at) (?:the )?(?:tone|beep)\b/i.test(
      text,
    ) ||
    /\byou(?:'ve| have) reached\b[\s\S]{0,120}\b(?:leave|record) (?:me |us )?(?:a |your )?message\b/i.test(
      text,
    ) ||
    /\b(?:cannot|can't|unable to) (?:take|answer) your call\b[\s\S]{0,120}\b(?:leave|record) (?:a |your )?message\b/i.test(
      text,
    ) ||
    /\b(?:has been |have been |is being )?forwarded to (?:an? |the )?(?:automatic|automated) (?:voice[ -]?(?:messag(?:e|ing)|mail)|messaging) system\b/i.test(
      text,
    ) ||
    /\b(?:please )?leave (?:me |us )?(?:a |your )?(?:voice[ -]?)?message\b[\s\S]{0,160}\b(?:after|at) (?:the )?(?:tone|beep)\b/i.test(
      text,
    ) ||
    /\b(?:at|after) the (?:tone|beep)\b[\s\S]{0,120}\b(?:record|leave) (?:a |your )?message\b/i.test(
      text,
    ) ||
    /\bplease (?:record|reply|speak)(?: (?:your|a|an additional) (?:message|reply))? (?:after|at) (?:the )?(?:tone|beep)\b/i.test(
      text,
    ) ||
    /\b(?:the|this) (?:person|subscriber|number|mailbox)\b[\s\S]{0,100}\b(?:not available|unavailable|cannot accept|can't accept)\b[\s\S]{0,100}\b(?:message|voicemail|mailbox)\b/i.test(
      text,
    ) ||
    /\b(?:leave|record) (?:me |us )?(?:a |your )?(?:voice[ -]?)?message\b.{0,120}\b(?:after|at) the (?:tone|beep)\b/i.test(
      prompt,
    ) ||
    /\b(?:you(?:'ve| have) reached|(?:cannot|can't|unable to) (?:take|answer) your call)\b.{0,120}\b(?:leave|record) (?:me |us )?(?:a |your )?message\b/i.test(
      prompt,
    ) ||
    /\b(?:your|this) call (?:has been|is being|was) forwarded (?:to )?(?:an? |the )?(?:(?:automatic|automated) (?:voice[ -]?)?messaging system|voice[ -]?mail)\b/i.test(
      prompt,
    )
  );
}
module.exports = { isVoicemailGreeting };
